/* @preserve Cookie Consent Init */
function createCookie(name,value,days){var expires="";if(days){var date=new Date;date.setTime(date.getTime()+days*24*60*60*1e3);expires="; expires="+date.toUTCString()}document.cookie=`${name}=${value}${expires}; path=/`}function readCookie(name){var nameEQ=name+"=";var ca=document.cookie.split(";");for(var i=0;i<ca.length;i++){var c=ca[i];while(c.charAt(0)===" ")c=c.substring(1,c.length);if(c.indexOf(nameEQ)===0)return c.substring(nameEQ.length,c.length)}return null}function addCookieConsentListener(){document.getElementById("cookie-notice-accept").addEventListener("click",function(){createCookie(cookieName,"true",31);document.getElementById("cookie-notice").style.display="none";location.reload()})}function googleAnalytics(){if(analyticsName.toLowerCase()!==""){window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments)}gtag("js",new Date);gtag("config",analyticsName);window.ga=window.ga||function(){(ga.q=ga.q||[]).push(arguments)};ga.l=+new Date;ga("create",analyticsName,"auto");ga("send","pageview")}}if(isCookieConsent.toLowerCase()==="true"){addCookieConsentListener();if(readCookie(cookieName)==="true"){googleAnalytics()}else{document.getElementById("cookie-notice").style.display="block"}}else{googleAnalytics()}/* @preserve Dark mode Init */
const themeButton={light:'<i class="fas fa-adjust" aria-hidden="true"></i>',dark:'<i class="fas fa-adjust fa-rotate-180" aria-hidden="true"></i>'};const currentTheme=()=>sessionStorage.getItem("theme");function setMode(theme){document.documentElement.setAttribute("data-theme",theme);sessionStorage.setItem("theme",theme);document.getElementById("theme-toggle").innerHTML=themeButton[theme]}function themeToggle(){let sessionPrefers=currentTheme();if(sessionPrefers==="light"){setMode("dark")}else{setMode("light")}}window.onload=function bootstrapTheme(){if(isAutoTheme){if(!currentTheme()){let browserPrefersDark=window.matchMedia("(prefers-color-scheme: dark)");browserPrefersDark.addEventListener("change",()=>{if(browserPrefersDark.matches)sessionStorage.setItem("theme","dark")})}let sessionPrefers=currentTheme();setMode(sessionPrefers?sessionPrefers:"light")}};/* @preserve Navbar */
document.addEventListener("DOMContentLoaded",function(event){const pull=document.getElementById("pull");const menu=document.querySelector("nav ul");["click","touch"].forEach(function(e){pull.addEventListener(e,function(){menu.classList.toggle("hide")},false)});window.addEventListener("scroll",function(){const offset=-(window.scrollY||window.pageYOffset||document.body.scrollTop)/3;document.getElementById("main").style.backgroundPosition="100% "+(offset-50)+"px"+", 0%, center top"})});